                idx += 1
            if idx >= len(lines):
                break
            current_line = lines[idx].strip()
            idx += 1
            if current_line == 'STOP':
                break
            commands.append(current_line)
        # Process commands
        i, j = 1, 1
        direction = 0  # 0: north, 1: east, 2: south, 3: west
        for cmd in commands:
            if cmd == 'RIGHT':
                direction = (direction + 1) % 4
            elif cmd == 'LEFT':
                direction = (direction - 1) % 4
            elif cmd.startswith('FORWARD') or cmd.startswith('BACKWARD'):
                parts = cmd.split()
                k = int(parts[1])
                direction_vectors = [(0, 1), (1, 0), (0, -1), (-1, 0)]
